@push('scripts')<script>
document.getElementById('pub_later')?.addEventListener('change', function(){ document.getElementById('schedule_wrap').classList.toggle('hidden', !this.checked); });
document.getElementById('add_class')?.addEventListener('change', function(){ const cid=this.value; fetch('{{ route('ajax.getSectionByClass') }}', {method:'POST', headers:{'X-CSRF-TOKEN':'{{ csrf_token() }}','Content-Type':'application/json'}, body: JSON.stringify({class_id: cid})}).then(r=>r.text()).then(html=>{ document.getElementById('add_section').innerHTML=html; }); fetch('{{ route('ajax.getSubjectByClass') }}', {method:'POST', headers:{'X-CSRF-TOKEN':'{{ csrf_token() }}','Content-Type':'application/json'}, body: JSON.stringify({class_id: cid})}).then(r=>r.text()).then(html=>{ document.getElementById('add_subject').innerHTML=html; }); });
document.getElementById('add_branch')?.addEventListener('change', function(){ fetch('{{ route('ajax.getClassByBranch') }}', {method:'POST', headers:{'X-CSRF-TOKEN':'{{ csrf_token() }}','Content-Type':'application/json'}, body: JSON.stringify({branch_id: this.value})}).then(r=>r.text()).then(html=>{ document.getElementById('add_class').innerHTML=html; }); });
</script>@endpush
